#ifndef GALAXYVITA_NAND_H
#define GALAXYVITA_NAND_H

#include "common/types.h"

#include <stdio.h>

/* ISFS backend over a host directory. Guest paths ("/shared2/sys/SYSCONF")
 * map to <root>/shared2/sys/SYSCONF. The tree is generated by
 * scripts/make-nand.py — it holds no Nintendo data, only the SYSCONF and
 * setting.txt this port synthesises. */

enum { NAND_HANDLES = 16, NAND_PATH_MAX = 96 };

enum {
  NAND_MODE_READ = 1,
  NAND_MODE_WRITE = 2,
  NAND_MODE_RW = 3
};

/* IOS FS return codes: -(ResultCode + 100), matching Dolphin's ConvertResult. */
#define NAND_OK 0
#define NAND_EINVAL (-101)
#define NAND_EACCES (-102)
#define NAND_EEXIST (-105)
#define NAND_ENOENT (-106)
#define NAND_ENFILE (-109)

typedef struct NandHandle {
  FILE *fp;
  u32 size;
  int used;
  int mode;
  char path[NAND_PATH_MAX];
} NandHandle;

typedef struct Nand {
  char root[512];
  NandHandle h[NAND_HANDLES];
  u32 opens;
  u32 reads;
  u32 writes;
  u32 misses;
  int opened;
} Nand;

int nand_open(Nand *n, const char *root);
void nand_close(Nand *n);

/* All of these return a handle index (>= 0) or a negative IOS FS code. */
s32 nand_file_open(Nand *n, const char *guest_path, int mode);
s32 nand_file_close(Nand *n, s32 h);
s32 nand_file_read(Nand *n, s32 h, void *dst, u32 len);
s32 nand_file_write(Nand *n, s32 h, const void *src, u32 len);
s32 nand_file_seek(Nand *n, s32 h, s32 offset, u32 whence);
s32 nand_file_stats(Nand *n, s32 h, u32 *size, u32 *pos);

s32 nand_create_file(Nand *n, const char *guest_path);
s32 nand_create_dir(Nand *n, const char *guest_path);
s32 nand_delete(Nand *n, const char *guest_path);
s32 nand_rename(Nand *n, const char *from, const char *to);
s32 nand_exists(Nand *n, const char *guest_path);
/* Pack up to `max` NUL-terminated entry names into `names` (a buffer of at
 * least max*13 bytes; IOS packs the names end to end, it does not stride).
 * `*total` receives the real entry count. Returns how many were packed, or a
 * negative IOS FS code. */
s32 nand_read_dir(Nand *n, const char *guest_path, char *names, u32 max,
                  u32 *total);

#endif
